import { User } from '@/service/user.service'
import { getToasterPromisSuccess } from '@/utiles/getToasterPromisSuccess'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import { SubmitHandler, useForm } from 'react-hook-form'
import toast from 'react-hot-toast'

interface IEditForm {
  avatar?: FileList
  fullname: string
  email: string
  dateOfBirth: string
  postalCode: string
  username: string
  city: string
  country: string
}

export const useEditForm = (formValues: IEditForm) => {
  const queryClient = useQueryClient()

  const createUserAboutMutation = useMutation({
    mutationFn: User.patchUserAbout,

    async onSettled() {
      await queryClient.invalidateQueries({
        queryKey: ['user'],
      })
    },
  })

  const createUserAvatarMutation = useMutation({
    mutationFn: User.uploadAvatar,

    async onSettled() {
      await queryClient.invalidateQueries({
        queryKey: ['user'],
      })
    },
  })
  const isPendingAbout = createUserAboutMutation.isPending
  const isPendingAvatar = createUserAvatarMutation.isPending

  const {
    reset,
    handleSubmit,
    register,
    formState: { errors },
  } = useForm<IEditForm>({
    defaultValues: {
      ...formValues,
    },
  })

  const onSubmit: SubmitHandler<IEditForm> = (data) => {
    const { avatar, ...withOutAvatrData } = data
    if (avatar) {
      const formData = new FormData()
      formData.append('files', avatar[0])
      User.uploadAvatar(formData)
      // toast.promise(
      //   createUserAvatarMutation.mutateAsync({ avatar: formData }),
      //   {
      //     ...getToasterPromisSuccess('Avatar has been update'),
      //   }
      // )
    }
    toast.promise(
      createUserAboutMutation.mutateAsync({ ...withOutAvatrData }),
      {
        ...getToasterPromisSuccess('Profile has been update'),
      }
    )
    reset()
  }

  return {
    register,
    isPending: !(isPendingAbout === isPendingAvatar),
    reset,
    errors,
    formSubmit: handleSubmit(onSubmit),
  }
}
